const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const clubs=[['CSAB Judo','Cayenne','https://www.csab-judo.org'],['École des Arts Martiaux de Cayenne','Cayenne · Dojo de Suzini','https://www.eamc973.fr'],['Arts Martiaux Léon Damas','Cayenne · Mont-Lucas',''],['Judo Club Guyanais','Cayenne · Mont-Lucas',''],['Seyroku Samourai','Cayenne',''],['Judo Club 3e REI','Kourou',''],['Judo Spatial Kourou','Kourou',''],['JC Tonate Macouria','Macouria',''],['Judo Club Regina Toulouris','Régina',''],['JA Guyane Saint-Laurent Maroni','Saint-Laurent-du-Maroni',''],['Judo Club Chiba','Matoury',''],['Judo Club de Matoury','Matoury','']];
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const input=document.querySelector('#club-search'),results=document.querySelector('#club-results');let expanded=false;function renderClubs(){const q=normalize(input.value),list=clubs.filter(c=>normalize(c[0]+' '+c[1]).includes(q));results.replaceChildren();for(const [name,city,url]of list.slice(0,expanded||q?99:4)){const row=document.createElement('div');row.className='club-row';const info=document.createElement('div'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=name;p.textContent=city;info.append(h,p);row.append(info);const link=document.createElement(url?'a':'span');link.textContent=url?'Voir le site ↗':'Lien à renseigner';if(url){link.href=url;link.target='_blank';link.rel='noopener'}row.append(link);results.append(row)}if(!list.length){const p=document.createElement('p');p.textContent='Aucun club trouvé. Essayez une autre commune.';results.append(p)}document.querySelector('#all-clubs').hidden=!!q;document.querySelector('#all-clubs').textContent=expanded?'Réduire la liste ↑':'Voir les '+clubs.length+' clubs de l’annuaire ↓'}input.addEventListener('input',renderClubs);document.querySelector('#all-clubs').addEventListener('click',()=>{expanded=!expanded;renderClubs()});document.querySelectorAll('[data-city]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.city;renderClubs();input.focus()}));renderClubs();
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const category=b.dataset.category;document.querySelector('#agenda-label').textContent=category==='Tous'?'LE CALENDRIER SE PRÉPARE':category.toUpperCase();document.querySelector('#agenda-title').textContent=category==='Tous'?'Les prochaines dates arrivent ici.':'Les dates « '+b.textContent+' » seront annoncées ici.'}));
